test("marks tree-shakeable generated message layouts as side-effect-free", async () => {
	const project = await loadProjectInMemory({
		blob: await newProject({
			settings: {
				locales: ["en", "de"],
				baseLocale: "en",
			},
		}),
	});

	const messageModules = await compileProject({
		project,
	});

	const localeModules = await compileProject({
		project,
		compilerOptions: { outputStructure: "locale-modules" },
	});
	const specializedLocaleModules = await compileProject({
		project,
		compilerOptions: {
			outputStructure: "locale-modules",
			experimentalStaticLocale: perLocaleBuildStaticLocaleExpression,
		},
	});

	// message-modules: the message modules are side-effect-free, so bundlers can
	// drop unused re-exports from the `m` barrel per entry instead of emitting one
	// shared chunk with every message. `type: "module"` keeps the generated ESM
	// files in the new `messages/` package scope from defaulting to CommonJS.
	expect(messageModules).toHaveProperty("messages/package.json");
	expect(JSON.parse(messageModules["messages/package.json"]!)).toEqual({
		type: "module",
		sideEffects: false,
	});

	expect(localeModules).not.toHaveProperty("messages/package.json");
	expect(specializedLocaleModules).toHaveProperty("messages/package.json");
	expect(
		JSON.parse(specializedLocaleModules["messages/package.json"]!)
	).toEqual({
		type: "module",
		sideEffects: false,
	});
});

test("inlines static text and retains only fallback helpers under strict checkJs", async () => {
	const project = await loadProjectInMemory({
		blob: await newProject({
			settings: {
				baseLocale: "en",
				locales: ["en", "de", "de-AT"],
			},
		}),
	});

	await insertBundleNested(
		project.db,
		createBundleNested({
			id: "plain_greeting",
			messages: [
				{
					locale: "en",
					variants: [{ pattern: [{ type: "text", value: "Hello" }] }],
				},
				{
					locale: "de",
					variants: [{ pattern: [{ type: "text", value: "Hallo" }] }],
				},
			],
		})
	);

	const output = await compileProject({
		project,
		compilerOptions: { outputStructure: "message-modules" },
	});
	const messageModule = output["messages/plain_greeting.js"]!;

	// The base locale is returned inline, while de-AT's missing-locale alias
	// still needs the de message function.
	expect(messageModule).not.toContain("const en_plain_greeting =");
	expect(messageModule).toContain("const de_plain_greeting =");
	expect(messageModule).toMatch(
		/const de_at\d*_plain_greeting = de_plain_greeting;/
	);

	const tsProject = await typescriptProject({
		useInMemoryFileSystem: true,
		compilerOptions: {
			outDir: "dist",
			declaration: true,
			allowJs: true,
			checkJs: true,
			noImplicitAny: true,
			noUnusedLocals: true,
			noUnusedParameters: true,
			noImplicitReturns: true,
			noImplicitThis: true,
			noUncheckedIndexedAccess: true,
			noPropertyAccessFromIndexSignature: true,
			module: ts.ModuleKind.Node16,
			strict: true,
		},
	});
	for (const [fileName, code] of Object.entries(output)) {
		if (fileName.endsWith(".js") || fileName.endsWith(".ts")) {
			tsProject.createSourceFile(fileName, code);
		}
	}
	const diagnostics = ts
		.getPreEmitDiagnostics(tsProject.createProgram())
		.filter(
			(d) =>
				!d.messageText.toString().includes("Cannot find module 'async_hooks'")
		);
	expect(diagnostics).toEqual([]);

	const { m } = await importCode(
		await bundleCode(output, `export * as m from "./paraglide/messages.js"`)
	);
	expect(m.plain_greeting({}, { locale: "en" })).toBe("Hello");
	expect(m.plain_greeting({}, { locale: "de" })).toBe("Hallo");
	expect(m.plain_greeting({}, { locale: "de-AT" })).toBe("Hallo");
});

test("inlines messages with inputs and plurals under strict checkJs", async () => {
	const project = await loadProjectInMemory({
		blob: await newProject({
			settings: {
				baseLocale: "en",
				locales: ["en", "de", "de-AT"],
			},
		}),
	});

	const text = (value: string): Pattern => [{ type: "text", value }];
	await insertBundleNested(
		project.db,
		createBundleNested({
			id: "welcome",
			declarations: [{ type: "input-variable", name: "name" }],
			messages: ["Hello", "Hallo"].map((greeting, index) => ({
				locale: index === 0 ? "en" : "de",
				variants: [
					{
						pattern: [
							{ type: "text", value: `${greeting} ` },
							{
								type: "expression",
								arg: { type: "variable-reference", name: "name" },
							},
						],
					},
				],
			})),
		})
	);
	await insertBundleNested(
		project.db,
		createBundleNested({
			id: "cats",
			declarations: [
				{ type: "input-variable", name: "count" },
				{
					type: "local-variable",
					name: "countPlural",
					value: {
						type: "expression",
						arg: { type: "variable-reference", name: "count" },
						annotation: {
							type: "function-reference",
							name: "plural",
							options: [],
						},
					},
				},
			],
			// de-AT has its own plural, so every locale declares `countPlural`.
			messages: [
				["en", "One cat", " cats"],
				["de", "Eine Katze", " Katzen"],
				["de-AT", "Ein Katzerl", " Katzerl"],
			].map(([locale, one, other]) => ({
				locale: locale!,
				selectors: [{ type: "variable-reference", name: "countPlural" }],
				variants: [
					{
						matches: [
							{ type: "literal-match", key: "countPlural", value: "one" },
						],
						pattern: text(one!),
					},
					{
						matches: [{ type: "catchall-match", key: "countPlural" }],
						pattern: [
							{
								type: "expression",
								arg: { type: "variable-reference", name: "count" },
							},
							{ type: "text", value: other! },
						],
					},
				],
			})),
		})
	);

	// The only declared input is never read, so the dispatcher marks it used.
	await insertBundleNested(
		project.db,
		createBundleNested({
			id: "unit_label",
			declarations: [
				{ type: "input-variable", name: "unused" },
				{
					type: "local-variable",
					name: "unit",
					value: {
						type: "expression",
						arg: { type: "literal", value: "kg" },
					},
				},
			],
			messages: [
				["en", "Weight in "],
				["de", "Gewicht in "],
				["de-AT", "Gewicht in "],
			].map(([locale, label]) => ({
				locale: locale!,
				variants: [
					{
						pattern: [
							{ type: "text", value: label! },
							{
								type: "expression",
								arg: { type: "variable-reference", name: "unit" },
							},
						],
					},
				],
			})),
		})
	);

	const output = await compileProject({
		project,
		compilerOptions: { outputStructure: "message-modules" },
	});

	// Only the message that de-AT's missing-locale alias calls keeps its function.
	expect(output["messages/welcome.js"]).not.toContain("const en_welcome =");
	expect(output["messages/welcome.js"]).toContain("const de_welcome =");
	expect(output["messages/cats.js"]).not.toMatch(/const \w+_cats =/);
	expect(output["messages/unit_label.js"]).not.toMatch(
		/const \w+_unit_label =/
	);

	const tsProject = await typescriptProject({
		useInMemoryFileSystem: true,
		compilerOptions: {
			outDir: "dist",
			declaration: true,
			allowJs: true,
			checkJs: true,
			noImplicitAny: true,
			noUnusedLocals: true,
			noUnusedParameters: true,
			noImplicitReturns: true,
			noImplicitThis: true,
			noUncheckedIndexedAccess: true,
			noPropertyAccessFromIndexSignature: true,
			module: ts.ModuleKind.Node16,
			strict: true,
		},
	});
	for (const [fileName, code] of Object.entries(output)) {
		if (fileName.endsWith(".js") || fileName.endsWith(".ts")) {
			tsProject.createSourceFile(fileName, code);
		}
	}
	const diagnostics = ts
		.getPreEmitDiagnostics(tsProject.createProgram())
		.map(
			(d) =>
				`${d.file?.fileName}: ${ts.flattenDiagnosticMessageText(d.messageText, "\n")}`
		)
		.filter((text) => !text.includes("Cannot find module 'async_hooks'"));
	expect(diagnostics).toEqual([]);

	const { m } = await importCode(
		await bundleCode(output, `export * as m from "./paraglide/messages.js"`)
	);
	expect(m.welcome({ name: "Ada" }, { locale: "en" })).toBe("Hello Ada");
	expect(m.welcome({ name: "Ada" }, { locale: "de" })).toBe("Hallo Ada");
	expect(m.welcome({ name: "Ada" }, { locale: "de-AT" })).toBe("Hallo Ada");
	expect(m.cats({ count: 1 }, { locale: "en" })).toBe("One cat");
	expect(m.cats({ count: 3 }, { locale: "en" })).toBe("3 cats");
	expect(m.cats({ count: 3 }, { locale: "de" })).toBe("3 Katzen");
	expect(m.cats({ count: 1 }, { locale: "de" })).toBe("Eine Katze");
	expect(m.cats({ count: 1 }, { locale: "de-AT" })).toBe("Ein Katzerl");
	expect(m.cats({ count: 3 }, { locale: "de-AT" })).toBe("3 Katzerl");
	expect(m.unit_label({ unused: 1 }, { locale: "en" })).toBe("Weight in kg");
	expect(m.unit_label({ unused: 1 }, { locale: "de-AT" })).toBe(
		"Gewicht in kg"
	);
});

