				runtime.setLocale("de");
				expect(mockOnSetLocale).toHaveBeenLastCalledWith("de");

				runtime.setLocale("en");
				expect(mockOnSetLocale).toHaveBeenLastCalledWith("en");

				expect(mockOnSetLocale).toHaveBeenCalledTimes(2);
